export function subtotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

export function discountAmount(subtotalValue, discount) {
  if (!discount) {
    return 0;
  }
  if (discount.type === 'percent') {
    return Math.round(subtotalValue * discount.value) / 100;
  }
  return Math.min(subtotalValue, discount.value);
}

export function totalWithTax(items, options = {}) {
  const beforeDiscount = subtotal(items);
  const discounted = Math.max(0, beforeDiscount - discountAmount(beforeDiscount, options.discount));
  const taxRate = options.taxRate ?? 0;
  return Math.round(discounted * (1 + taxRate) * 100) / 100;
}

headFiles.test/cart.test.js:
import test from 'node:test';
import assert from 'node:assert/strict';
import { discountAmount, subtotal, totalWithTax } from '../src/cart.js';

test('subtotal adds item totals', () => {
  assert.equal(subtotal([{ price: 12, quantity: 2 }, { price: 5, quantity: 1 }]), 29);
});

test('discountAmount handles percentage discounts', () => {
  assert.equal(discountAmount(200, { type: 'percent', value: 15 }), 30);
});

test('discountAmount caps fixed discounts at the subtotal', () => {
  assert.equal(discountAmount(20, { type: 'fixed', value: 99 }), 20);
});

test('totalWithTax applies discount before tax', () => {
  const items = [{ price: 50, quantity: 2 }];
  assert.equal(totalWithTax(items, { discount: { type: 'fixed', value: 10 }, taxRate: 0.1 }), 99);
});
